<template><section class="profiles-page"><div class="page-heading"><div><p class="page-eyebrow">管理员配置</p><h2>系统配置</h2><p>维护模型服务与知识库服务，连接凭据仅以环境变量引用保存。</p></div><el-button type="primary" @click="openCreate"><Plus :size="15" />{{ kind==='model'?'新增模型服务':'新增知识库服务' }}</el-button></div><div v-if="errorMessage" class="notice">{{ errorMessage }}<button @click="refresh">重试</button></div><div class="profile-tabs"><button :class="{active:kind==='model'}" @click="kind='model'">模型服务 <span>{{modelProfiles.length}}</span></button><button :class="{active:kind==='knowledge'}" @click="kind='knowledge'">知识库服务 <span>{{knowledgeProfiles.length}}</span></button></div><div v-if="loading">正在读取系统配置...</div><table v-else class="profile-table"><thead><tr><th>名称</th><th>服务说明</th><th>状态</th><th></th></tr></thead><tbody><tr v-for="p in activeProfiles" :key="p.id"><td><strong>{{p.name}}</strong><span>{{p.description||'暂无说明'}}</span></td><td>{{summary(p)}}</td><td>{{'is_active' in p&&!p.is_active?'停用':'启用'}}</td><td><button @click="openEdit(p)"><Pencil :size="15"/></button></td></tr></tbody></table><div v-if="!loading&&!activeProfiles.length" class="empty-state">还没有服务。</div><el-dialog v-model="dialogVisible" :title="editing?'编辑':'新增'" width="min(720px, calc(100vw - 32px))"><el-form v-if="kind==='model'" label-position="top"><h3>基本信息</h3><div class="form-grid"><el-form-item label="名称"><el-input v-model="modelForm.name"/></el-form-item><el-form-item label="说明"><el-input v-model="modelForm.description"/></el-form-item></div><div class="switch-row"><el-form-item label="启用服务"><el-switch v-model="modelForm.is_active"/></el-form-item><el-form-item label="对医学用户开放"><el-switch v-model="modelForm.exposed_to_medical"/></el-form-item></div><h3>模型连接</h3><div class="form-grid"><el-form-item label="接口类型"><el-input model-value="OpenAI 兼容接口" readonly/></el-form-item><el-form-item label="服务地址"><el-input v-model="modelForm.base_url"/></el-form-item><el-form-item label="模型"><el-input v-model="modelForm.model"/></el-form-item><el-form-item label="密钥环境变量引用"><el-input v-model="modelForm.api_key_ref"/></el-form-item></div><h3>运行参数</h3><div class="form-grid"><el-form-item label="温度"><el-input v-model="modelForm.temperature"/></el-form-item><el-form-item label="采样概率"><el-input v-model="modelForm.top_p"/></el-form-item><el-form-item label="最大输出长度"><el-input v-model="modelForm.max_tokens"/></el-form-item><el-form-item label="超时（秒）"><el-input v-model="modelForm.timeout"/></el-form-item><el-form-item label="重试次数"><el-input v-model="modelForm.retries"/></el-form-item></div><h3>医学说明</h3><div class="form-grid"><el-form-item label="显示名称"><el-input v-model="modelForm.display_name"/></el-form-item><el-form-item label="临床适用范围"><el-input v-model="modelForm.clinical_scope"/></el-form-item><el-form-item label="支持任务"><el-input v-model="modelForm.supported_tasks"/></el-form-item><el-form-item label="输出风格"><el-input v-model="modelForm.output_style"/></el-form-item></div><el-button :loading="testing" @click="runTest">测试连接</el-button><span v-if="testMessage">{{testMessage}}</span></el-form><el-form v-else label-position="top"><el-form-item label="名称"><el-input v-model="knowledgeForm.name"/></el-form-item><el-form-item label="说明"><el-input v-model="knowledgeForm.description"/></el-form-item><el-form-item label="对医学用户开放"><el-switch v-model="knowledgeForm.exposed_to_medical"/></el-form-item><el-form-item label="医学语义选项 JSON"><el-input v-model="knowledgeForm.medical_options" type="textarea"/></el-form-item><el-form-item label="技术配置 JSON"><el-input v-model="knowledgeForm.technical_config" type="textarea"/></el-form-item></el-form><p v-if="formError">{{formError}}</p><template #footer><el-button @click="dialogVisible=false">取消</el-button><el-button type="primary" :loading="saving" @click="save">保存</el-button></template></el-dialog></section></template>
<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'; import { Pencil, Plus } from 'lucide-vue-next'; import { getApiError } from '@/api/client'; import { createKnowledgeProfile, createModelProfile, listKnowledgeProfiles, listModelProfiles, patchKnowledgeProfile, patchModelProfile, testModelProfile } from '@/api/profiles'; import { modelFormToPayload, modelProfileToForm, type ModelProfileForm } from '@/composables/useModelProfileForm'; import type { Profile, ProfileCreatePayload } from '@/types/api'
const kind=ref<'model'|'knowledge'>('model'), modelProfiles=ref<Profile[]>([]), knowledgeProfiles=ref<Profile[]>([]), loading=ref(false), saving=ref(false), testing=ref(false), dialogVisible=ref(false), editing=ref<Profile|null>(null), errorMessage=ref(''), formError=ref(''), testMessage=ref(''); const modelForm=reactive<ModelProfileForm>(modelProfileToForm()), knowledgeForm=reactive({name:'',description:'',exposed_to_medical:true,medical_options:'{}',technical_config:'{}'}); const activeProfiles=computed(()=>kind.value==='model'?modelProfiles.value:knowledgeProfiles.value); onMounted(refresh)
async function refresh(){loading.value=true;try{[modelProfiles.value,knowledgeProfiles.value]=await Promise.all([listModelProfiles(),listKnowledgeProfiles()])}catch(e){errorMessage.value=getApiError(e).message}finally{loading.value=false}} function summary(p:Profile){return 'technical_config' in p&&typeof p.technical_config.model==='string'?`模型：${p.technical_config.model}`:'服务配置'} function openCreate(){editing.value=null;formError.value='';testMessage.value='';if(kind.value==='model')Object.assign(modelForm,modelProfileToForm());else Object.assign(knowledgeForm,{name:'',description:'',exposed_to_medical:true,medical_options:'{}',technical_config:'{}'});dialogVisible.value=true} function openEdit(p:Profile){editing.value=p;if(kind.value==='model')Object.assign(modelForm,modelProfileToForm(p));else Object.assign(knowledgeForm,{name:p.name,description:p.description||'',exposed_to_medical:p.exposed_to_medical,medical_options:JSON.stringify(p.medical_options),technical_config:JSON.stringify('technical_config'in p?p.technical_config:{})});dialogVisible.value=true}
async function runTest(){testing.value=true;testMessage.value='';try{const r=await testModelProfile(modelFormToPayload(modelForm).technical_config as never);testMessage.value=r.ok?`连接成功：${r.model}，耗时 ${r.latency_ms} 毫秒`:'连接未通过'}catch(e){testMessage.value=getApiError(e).message}finally{testing.value=false}} async function save(){formError.value='';saving.value=true;try{if(kind.value==='model'){const payload=modelFormToPayload(modelForm);const n=editing.value?await patchModelProfile(editing.value.id,payload):await createModelProfile(payload);modelProfiles.value=editing.value?modelProfiles.value.map(x=>x.id===n.id?n:x):[n,...modelProfiles.value]}else{const payload:ProfileCreatePayload={name:knowledgeForm.name,description:knowledgeForm.description,exposed_to_medical:knowledgeForm.exposed_to_medical,medical_options:JSON.parse(knowledgeForm.medical_options),technical_config:JSON.parse(knowledgeForm.technical_config)};const n=editing.value?await patchKnowledgeProfile(editing.value.id,payload):await createKnowledgeProfile(payload);knowledgeProfiles.value=editing.value?knowledgeProfiles.value.map(x=>x.id===n.id?n:x):[n,...knowledgeProfiles.value]}dialogVisible.value=false}catch(e){formError.value=getApiError(e).message}finally{saving.value=false}}
</script><style scoped>.profiles-page{max-width:1250px;margin:0 auto}.page-heading{display:flex;justify-content:space-between}.profile-tabs{display:flex;gap:8px;margin:20px 0}.profile-tabs button.active{font-weight:700}.profile-table{width:100%;border-collapse:collapse}.profile-table th,.profile-table td{padding:12px;text-align:left;border-bottom:1px solid var(--line)}.profile-table span,.profile-table strong{display:block}.form-grid{display:grid;grid-template-columns:1fr 1fr;gap:0 14px}.switch-row{display:flex;gap:24px}.empty-state{padding:30px;text-align:center}h3{margin:15px 0 8px}@media(max-width:700px){.form-grid{grid-template-columns:1fr}.page-heading{display:block}}</style>
